let __v_132 = { let mut __items_133 = Vec::new(); let __v_134 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"yogurt\",\"yoghurt\",\"yoghurts\",\"yogurts\",\"fromage frais\",\"greek yogurt\",\"greek yoghurt\",\"kefir\",\"skyr\"]}],[\"reply\",\"Yes, plain full-fat yoghurt is fine from six months. Buy natural or Greek rather than the children's fruit pots, which are mostly sugar - stir in mashed fruit instead - and give it with a meal rather than as a drink.\"]]}")?; __items_133.push(__v_134); let __v_135 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"cheese\",\"cheddar\",\"cheeses\",\"parmesan\",\"mozzarella\",\"cream cheese\",\"brie\",\"camembert\",\"blue cheese\",\"stilton\",\"gorgonzola\",\"roquefort\",\"mould ripened\",\"mold ripened\",\"soft cheese\",\"goats cheese\",\"feta\"]}],[\"reply\",\"Yes, from six months, in small amounts, because cheese is salty: about 25g a day is plenty for a little one. Stick to pasteurised cheese - brie, camembert and blue cheese are the ones to leave raw, and they are fine once cooked until steaming hot.\"]]}")?; __items_133.push(__v_135); let __v_136 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"egg\",\"eggs\",\"scrambled egg\",\"boiled egg\",\"omelette\"]}],[\"reply\",\"Yes, well cooked, from six months: scrambled egg, a hard-boiled egg mashed with a fork, or omelette cut into fingers. An egg with the red lion stamp can be given runny because those hens are vaccinated; without the stamp, cook it until white and yolk are both solid.\"]]}")?; __items_133.push(__v_136); let __v_137 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"strawberry\",\"strawberries\",\"raspberry\",\"raspberries\",\"blueberry\",\"blueberries\",\"berries\",\"blackberries\"]}],[\"reply\",\"Yes, from six months - cut them in half or quarters, because a round berry is a choking shape. Berries are acidic, so they can bring on a red nappy rash, and that is not an allergy; a rash round the mouth that fades on its own is usually the same thing.\"]]}")?; __items_133.push(__v_137); let __v_138 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"peanut butter\",\"peanut\",\"peanuts\",\"nut butter\",\"almond butter\",\"nut\",\"nuts\",\"almonds\",\"cashews\",\"almond\"]}],[\"reply\",\"Yes, and early is better than late: from six months, a thin smear of smooth peanut butter on toast or stirred into porridge. Never a spoonful on its own and never a whole nut - those are choking shapes, so use ground or butter only. Offer it on a day they are well, in the morning, then keep it in their week.\"]]}")?; __items_133.push(__v_138); let __v_139 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"raisins\",\"raisin\",\"sultanas\",\"sultana\",\"dried fruit\",\"dried apricots\",\"prunes\",\"dates\",\"currants\",\"cranberries\",\"dried cranberries\"]}],[\"reply\",\"Yes, from six months, but chop them: a whole raisin is the shape that blocks a small throat and it is sticky enough to sit on the teeth, so cut each one in half, give them with a meal rather than as a snack on their own, and keep them to a small handful a day. Dried fruit counts as one of the five a day, so it is not a substitute for fresh fruit - and never dried fruit with added sugar or yoghurt coating.\"]]}")?; __items_133.push(__v_139); let __v_140 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"tea\",\"teas\",\"green tea\",\"herbal tea\",\"camomile tea\",\"chamomile tea\",\"peppermint tea\",\"fruit tea\",\"coffee\",\"cola\",\"coke\",\"energy drink\",\"energy drinks\",\"caffeine\",\"fizzy drink\",\"fizzy drinks\",\"diet coke\"]}],[\"extra\",{\"$tuple\":[\"child\",\"children\",\"kid\",\"kids\",\"toddler\",\"toddlers\",\"teen\",\"teens\",\"teenager\",\"teenagers\",\"school\",\"year old\",\"12\",\"under 12\",\"10\",\"14\",\"dehydrat\",\"dehydrate\",\"dehydrates\",\"dehydrated\",\"dehydrating\",\"dehydration\",\"hydrate\",\"hydrated\",\"hydration\"]}],[\"bias\",3],[\"reply\",\"No, not as a drink: tea and coffee both carry caffeine a small body does not need, and the tannins in tea stop iron being absorbed, which matters most in the first two years. Cola, energy drinks and fizzy drinks are the same answer with sugar on top, and herbal teas are no better for a baby. Milk and water are the drinks: breast milk or formula before one, whole cows milk from one, and water in an open cup with meals from six months.\"]]}")?; __items_133.push(__v_140); let __v_141 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"liver\",\"lamb's liver\",\"chicken liver\",\"kidney\",\"pate\",\"liver pate\",\"paté\"]}],[\"reply\",\"Liver is fine from six months, but once a week at most: it is packed with vitamin A and iron, and too much vitamin A builds up. Cook it through, mash or blend it into something they already eat, and count liver, liver pate and cod liver oil as the same thing in that week. Pate itself is salty, so leave that until after the first birthday and then keep it to a thin scrape.\"]]}")?; __items_133.push(__v_141); let __v_142 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"crisps\",\"crisp\",\"chips\",\"wotsits\",\"quavers\",\"cheese puffs\"]}],[\"reply\",\"No, not before one, and rarely after: crisps are salty and they are a choking shape, and the same goes for chips with salt on. A handful of soft veg sticks, toast fingers or a bit of cheese is the same idea without the salt.\"]]}")?; __items_133.push(__v_142); let __v_143 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"wheat\",\"soya\",\"soy\",\"sesame\",\"gluten\"]}],[\"reply\",\"Yes, from six months, and early is the point: wheat, soya and sesame are three of the allergens to give in the first year, one at a time, on a day they are well and in the morning. Bread, pasta, cereal, tofu and tahini all count, and once a food is in, keep giving it a couple of times a week rather than stopping.\"]]}")?; __items_133.push(__v_143); let __v_144 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"cows milk\",\"cow's milk\",\"whole milk\",\"full fat milk\",\"semi skimmed milk\"]}],[\"reply\",\"Not as a drink before twelve months: it has too little iron and too much salt and protein for a baby. You can cook with it, or put a splash on cereal, from six months. From one, give whole milk, about 350 to 400ml a day.\"]]}")?; __items_133.push(__v_144); let __v_145 = { let __dict_146 = Value::dict(); let __v_147 = Value::from("names"); let __v_148 = { let mut __items_149 = Vec::new(); let __v_150 = Value::from("water"); __items_149.push(__v_150); let __v_151 = Value::from("juice"); __items_149.push(__v_151); let __v_152 = Value::from("fruit juice"); __items_149.push(__v_152); let __v_153 = Value::from("squash"); __items_149.push(__v_153); let __v_154 = Value::from("cordial"); __items_149.push(__v_154); let __v_155 = Value::from("orange juice"); __items_149.push(__v_155); let __v_156 = Value::from("apple juice"); __items_149.push(__v_156); let __v_157 = Value::from("smoothie"); __items_149.push(__v_157); let __v_158 = Value::from("smoothies"); __items_149.push(__v_158); let __v_159 = Value::from("milkshake"); __items_149.push(__v_159); let __v_160 = Value::from("milkshakes"); __items_149.push(__v_160); Value::tuple(__items_149) }; __dict_146.dict_set(__v_147, __v_148)?; let __v_161 = Value::from("own_ask"); let __v_162 = frame.load(rt, "_the_water_ask")?; __dict_146.dict_set(__v_161, __v_162)?; let __v_163 = Value::from("extra"); let __v_164 = { let mut __items_165 = Vec::new(); let __v_166 = Value::from("toddler"); __items_165.push(__v_166); let __v_167 = Value::from("toddlers"); __items_165.push(__v_167); let __v_168 = Value::from("litre"); __items_165.push(__v_168); let __v_169 = Value::from("litres"); __items_165.push(__v_169); let __v_170 = Value::from("2 year"); __items_165.push(__v_170); let __v_171 = Value::from("3 year"); __items_165.push(__v_171); let __v_172 = Value::from("4 year"); __items_165.push(__v_172); let __v_173 = Value::from("5 year"); __items_165.push(__v_173); let __v_174 = Value::from("child"); __items_165.push(__v_174); let __v_175 = Value::from("children"); __items_165.push(__v_175); let __v_176 = Value::from("kids"); __items_165.push(__v_176); let __v_177 = Value::from("i drink"); __items_165.push(__v_177); let __v_178 = Value::from("should i drink"); __items_165.push(__v_178); let __v_179 = Value::from("how much should i"); __items_165.push(__v_179); Value::tuple(__items_165) }; __dict_146.dict_set(__v_163, __v_164)?; let __v_180 = Value::from("reply"); let __v_181 = Value::from("Not before six months - milk is all they need, and extra water can upset their salts. From six months, water is the drink to offer in an open cup with meals, and juice or squash is not needed at any age: if you give it, wait until twelve months, dilute it, and keep it to a meal in a cup rather than a bottle."); __dict_146.dict_set(__v_180, __v_181)?; __dict_146 }; __items_133.push(__v_145); let __v_182 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"salt\",\"salty\",\"stock cube\",\"stock cubes\",\"gravy\",\"bacon\",\"ham\",\"sausages\",\"sausage\",\"salted\",\"marmite\",\"yeast extract\",\"bovril\",\"soy sauce\",\"baked beans\",\"beans on toast\",\"tomato ketchup\",\"ketchup\",\"brown sauce\",\"mayonnaise\",\"mayo\",\"soup\",\"soups\",\"gravy granules\",\"stock\",\"salted butter\"]}],[\"reply\",\"No salt at all in their food before one, and very little after: a baby's kidneys cannot cope with it. That rules out stock cubes, gravy granules, bacon, ham, sausages and most sauces - cook their portion separately and season yours.\"]]}")?; __items_133.push(__v_182); let __v_183 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"sugar\",\"sweets\",\"chocolate\",\"biscuits\",\"biscuit\",\"cake\",\"cakes\",\"jelly\",\"jam\",\"marmalade\",\"rice pudding\",\"custard\"]}],[\"reply\",\"There is no need for sugar at all before two, and it is worth keeping it that way while you can, because it is what makes them prefer sweet food later. Fruit is the sweet thing to give, and cheese or toast makes a better snack than a biscuit.\"]]}")?; __items_133.push(__v_183); let __v_184 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"grapes\",\"grape\",\"cherry tomatoes\",\"cherries\",\"olives\",\"hot dog\",\"hot dogs\"]}],[\"reply\",\"Yes, but cut them: grapes, cherry tomatoes and olives go lengthways into quarters and sausages lengthways into strips, because the round shape is what blocks a small throat. Whole grapes are the food toddlers choke on most, and popcorn is not one to give before about four.\"]]}")?; __items_133.push(__v_184); let __v_185 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"popcorn\",\"pop corn\",\"puffed corn\",\"corn snacks\"]}],[\"reply\",\"No, not before about four: popcorn is light, hard and the exact shape that lodges in a small airway, and it is the food toddlers choke on most after grapes. Puffed corn snacks are the same shape and salty as well, so leave those too, and keep crisps for an occasional treat after one, sitting down.\"]]}")?; __items_133.push(__v_185); let __v_186 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"rice cake\",\"rice cakes\",\"corn cake\",\"corn cakes\",\"oat cake\",\"oat cakes\",\"crackers\",\"cracker\",\"breadsticks\",\"bread sticks\",\"rusks\",\"rusk\"]}],[\"reply\",\"Yes, from six months, and they are good for the pincer grip - but read the packet first, because they are often the saltiest thing in the baby aisle. Unsalted rice cakes, plain oatcakes and no-salt breadsticks are the ones to pick; a rusk is mostly sugar, so treat it as a biscuit rather than a food.\"]]}")?; __items_133.push(__v_186); let __v_187 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"cucumber\",\"cucumbers\",\"tomato\",\"tomatoes\",\"bell pepper\",\"bell peppers\",\"red pepper\",\"green pepper\",\"sweet pepper\",\"lettuce\",\"celery\",\"radish\",\"radishes\",\"spring onion\",\"spring onions\",\"beetroot\",\"raw carrot\",\"carrot sticks\"]}],[\"reply\",\"Yes, from six months, raw or cooked: cucumber and tomato cut into finger-length batons or quarters are two of the easiest first finger foods, because a baby can hold them and gum them. Cherry tomatoes and olives go lengthways into quarters, and celery strings are worth peeling off before you hand it over.\"]]}")?; __items_133.push(__v_187); let __v_188 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"tofu\",\"bean curd\",\"edamame\",\"soya bean\",\"soy bean\",\"tempeh\"]}],[\"reply\",\"Yes, from six months, cooked through: tofu cut into strips is soft enough to gum, and it takes on whatever it is cooked in. It is soya, so introduce it the way you would peanut - a little on its own the first time, then watch for two hours - and keep it plain rather than in a salty marinade.\"]]}")?; __items_133.push(__v_188); let __v_189 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"quorn\",\"mycoprotein\",\"quorn mince\",\"quorn pieces\",\"meat free mince\",\"veggie mince\",\"vegetarian mince\"]}],[\"reply\",\"Yes, from six months, cooked through and chopped small: Quorn is mycoprotein, a fungal protein rather than soya, and the plain mince and pieces are low in salt and fine for a baby. It is a protein swap rather than a whole food, so give it with something iron-rich - lentils, beans or a little meat - and read the packet on the breaded and ready-made versions, which are salty.\"]]}")?; __items_133.push(__v_189); let __v_190 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"sushi\",\"sashimi\",\"raw fish\",\"raw prawns\",\"smoked salmon\",\"smoked mackerel\",\"gravadlax\",\"gravalax\",\"cured fish\",\"oysters\"]}],[\"reply\",\"Sushi is fine once the fish in it is cooked: a cooked prawn or salmon roll, or a vegetable one, is a good finger food from six months. Raw fish and raw shellfish wait until they are five, because of the parasites and the bones. Smoked salmon is cured rather than cooked and it is salty, so a flake now and then is the most of it.\"],[\"bias\",2]]}")?; __items_133.push(__v_190); let __v_191 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"fish\",\"salmon\",\"tuna\",\"cod\",\"prawns\",\"shellfish\",\"prawn\",\"mussels\"]}],[\"reply\",\"Yes, well cooked and with every bone out - flake it and check between your fingers first. Oily fish like salmon once or twice a week is worth having. Leave out shark, swordfish and marlin, and keep tuna to about one small tin a week.\"]]}")?; __items_133.push(__v_191); let __v_192 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"toast\",\"bread\",\"crumpet\",\"pitta\",\"cracker\",\"crackers\",\"chapati\",\"chapatis\",\"naan\",\"roti\",\"wrap\",\"wraps\",\"bagel\",\"bagels\",\"scone\",\"scones\",\"teacake\"]}],[\"reply\",\"Yes, from six months - toast fingers are one of the easiest first foods because a baby can hold them. White, wholemeal or a mix is fine; bread has salt in it already, which is a reason not to add more, not a reason to wait.\"],[\"pronoun\",true],[\"extra\",{\"$tuple\":[\"a toast\",\"raise a glass\",\"raise the glass\",\"speech\",\"speeches\",\"wedding\",\"best man\",\"eulogy\",\"few words\",\"say a few words\"]}]]}")?; __items_133.push(__v_192); let __v_193 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"banana\",\"bananas\"]}],[\"reply\",\"Yes, from six months, and it is one of the easiest first foods: mash it or cut it into finger-length pieces a baby can hold. It is sweet and soft, so it goes down on a day when nothing else does.\"]]}")?; __items_133.push(__v_193); let __v_194 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"avocado\",\"avocados\",\"guacamole\",\"avocado pear\"]}],[\"reply\",\"Yes, from six months: ripe avocado mashed on toast fingers, or in a wedge they can hold with the skin as a handle. The fat in it is the kind a growing baby needs, and its blandness sits well next to a stronger taste.\"]]}")?; __items_133.push(__v_194); let __v_195 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"broccoli\",\"cauliflower\",\"courgette\",\"carrot\",\"carrots\",\"sweet potato\",\"butternut squash\",\"parsnip\",\"peas\",\"green beans\",\"spinach\",\"kale\",\"leeks\",\"swede\",\"turnip\",\"asparagus\",\"plantain\",\"mushroom\",\"mushrooms\",\"mange tout\",\"sugar snap peas\",\"runner beans\",\"cabbage\",\"brussels sprouts\",\"cauliflower cheese\"]}],[\"reply\",\"Yes, from six months, cooked soft enough to squash between your fingers - a whole floret or a stick of carrot is a handle a baby can hold and gum. Keep offering the ones they refuse: it can take ten tries before a vegetable is eaten.\"]]}")?; __items_133.push(__v_195); let __v_196 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"potato\",\"potatoes\",\"mash\"]}],[\"reply\",\"Yes, from six months: mashed potato with a little of their usual milk or unsalted butter, or soft roast potato in strips. No salt in the water or on top, and skip chips and crisps, which are salty and hard to manage.\"]]}")?; __items_133.push(__v_196); let __v_197 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"pasta\",\"fusilli\",\"penne\",\"macaroni\",\"spaghetti\",\"noodles\"]}],[\"reply\",\"Yes, from about six months once they can pick things up: shapes like fusilli or penne are easier to hold than spaghetti, and cook them a minute past the packet so they are soft. Cut long pasta, and keep the sauce low in salt.\"]]}")?; __items_133.push(__v_197); let __v_198 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"rice\",\"couscous\",\"quinoa\",\"bulgur\"]}],[\"reply\",\"Yes, from six months, cooked soft - as a mash, or pressed into a sticky ball they can pick up. No salt in the water. Cooked rice is the one to be careful with: cool it fast, fridge it within the hour, and reheat it once, hot all through.\"]]}")?; __items_133.push(__v_198); let __v_199 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"hummus\",\"houmous\",\"chickpeas\"]}],[\"reply\",\"Yes, from six months: spread it thin on toast fingers or let them dip a finger of pitta in it, and it counts as a portion of protein. Shop hummus can be salty, so a plain one or your own is better.\"]]}")?; __items_133.push(__v_199); let __v_200 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"lentils\",\"dhal\",\"daal\",\"beans\",\"kidney beans\",\"chick pea\",\"pulses\"]}],[\"reply\",\"Yes, from six months: red lentils cook down into a thick dhal they can eat from a spoon or with bread, and mashed beans go into a sauce the same way. Pulses are a good source of iron, and a squeeze of lemon or some tomato helps the iron go in.\"]]}")?; __items_133.push(__v_200); let __v_201 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"mango\",\"melon\",\"watermelon\",\"peach\",\"pear\",\"plum\",\"nectarine\",\"blueberries\",\"raspberries\",\"kiwi\",\"kiwis\",\"pineapple\",\"coconut\",\"grated coconut\",\"strawberry\",\"strawberries\",\"blackberries\",\"cherries\",\"apricot\",\"apricots\",\"papaya\",\"fig\",\"figs\",\"orange\",\"satsuma\",\"mandarin\",\"clementine\"]}],[\"reply\",\"Yes, from six months: soft ripe fruit in strips or wedges they can hold, and a wedge with the skin on makes a handle to gnaw. Round fruit is the one to cut - berries in half, grapes lengthways - and stay with them while they eat it.\"]]}")?; __items_133.push(__v_201); let __v_202 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"chicken\",\"beef\",\"lamb\",\"pork\",\"mince\",\"meat\"]}],[\"reply\",\"Yes, from six months: soft cooked meat in strips they can hold, or minced into a sauce, and it is the best source of the iron a baby uses up at about six months. A strip of well-cooked chicken or a lamb chop bone is a good thing to gnaw, with the gristle and small bones taken out.\"]]}")?; __items_133.push(__v_202); let __v_203 = pyrt::literals::decode("{\"$dict\":[[\"names\",{\"$tuple\":[\"porridge\",\"oats\",\"cereal\",\"baby rice\"]}],[\"extra\",{\"$tuple\":[\"bottle\",\"bottles\",\"in a bottle\",\"in the bottle\",\"bottle feed\"]}],[\"reply\",\"Yes, from six months, and ordinary porridge oats made with their usual milk are as good as any baby cereal, with no added sugar or salt. Baby rice is almost all starch, so it fills them up without feeding them much.\"]]}")?; __items_133.push(__v_203); Value::tuple(__items_133) };
