let __v_204 = Value::from("Start with soft food they can hold themselves rather than something on a spoon: cooked carrot or broccoli, toast fingers, ripe pear, banana, avocado, or a spoon of plain yoghurt. One food at a time, a few days apart, so a reaction is easy to spot, and milk first so they are not too hungry to try. How much is a few spoonfuls or a few sticks at the start, half a fist by nine months and about a fist at a year. Around six months is the age, unless a health visitor has said otherwise.");
frame.store("_FIRST_FOODS", __v_204.clone())?;
