frame.store("_MILK_SIX_TO_TWELVE", __v_294.clone())?;
let __v_295 = Value::from("About 350 to 400ml (12oz) a day of whole cows milk from one, in a cup rather than a bottle: that much covers the calcium without filling them up before meals, and more than about 500ml crowds out the iron in food.");
