let __v_296 = Value::from("Under six months, none: milk is all they need and extra water can upset the salts in a small body. From six months, offer a little water in an open cup with meals - a few sips is enough, and they will take what they need rather than a set amount. From one, water with every meal and between meals as they ask for it, and that is when a cup measuring roughly a litre a day starts to make sense.");
frame.store("_WATER_UNDER_SIX", __v_296.clone())?;
let __v_297 = Value::from("Water with every meal and between meals whenever they ask for it: a cup measuring roughly a litre a day is the toddler figure, and the milk they drink counts towards it. Leave the cup where they can reach it and refill it without a fuss. Under six months it was none, because extra water upsets the salts in a small body, so do not go back to that unless a doctor says so.");
frame.store("_WATER_OVER_ONE", __v_297.clone())?;
